(function(){document.addEventListener("DOMContentLoaded",()=>{const t=document.querySelector('[id^="testimonial-slider-"]');if(!t)return;const n=t.id.replace("testimonial-slider-",""),l=document.querySelectorAll(".testimonial-dot-"+n);if(l.length===0)return;const d=()=>{const o=t.getBoundingClientRect(),s=o.left+o.width/2;let c=0,e=1/0;t.querySelectorAll(".testimonial-item-"+n).forEach((i,r)=>{const m=i.getBoundingClientRect(),u=m.left+m.width/2,f=Math.abs(s-u);f<e&&(e=f,c=r)}),l.forEach((i,r)=>{r===c?(i.style.backgroundColor="var(--color-primary)",i.style.opacity="1"):(i.style.backgroundColor="var(--color-outline-variant)",i.style.opacity="0.5")})};t.addEventListener("scroll",d),l.forEach((o,s)=>{o.addEventListener("click",()=>{const e=t.querySelectorAll(".testimonial-item-"+n)[s];if(e){const a=e.offsetLeft-(t.clientWidth-e.clientWidth)/2;t.scrollTo({left:a,behavior:"smooth"})}})}),d()})})();
